use desafio::oposto;
use desafio::oposto_da_soma;

#[test]
fn testa_oposto_de_tres_e_menos_tres() {
    assert_eq!(oposto(3), -3);
}

#[test]
fn testa_oposto_de_menos_tres_e_tres() {
    assert_eq!(oposto(-3), 3);
}

#[test]
fn testa_oposto_de_zero_e_zero() {
    assert_eq!(oposto(0), 0);
}

#[test]
fn testa_o_oposto_da_soma_positiva_e_da_negativa() {
    assert_eq!(oposto_da_soma(3, 4), -7);
    assert_eq!(oposto_da_soma(-2, -2), 4);
}
